prediction.compute:
data = read('/input/data')
rows = data['rows']
groups = {}
for r in rows:
    g = r['group']
    qty = r['qty']
    price = r['price']
    discount = r['discount']
    if g not in groups:
        groups = putmap(groups, g, {'count':0, 'units':0, 'net':0})
    entry = groups[g]
    new_entry = {'count': entry['count'] + 1, 'units': entry['units'] + qty, 'net': entry['net'] + (qty * price - discount)}
    groups = putmap(groups, g, new_entry)
sorted_groups = sorted(keys(groups))
main = []
for g in sorted_groups:
    entry = groups[g]
    main = main + [{'group': g, 'count': entry['count'], 'units': entry['units'], 'net': entry['net']}]
result = {'main': main}
